import {survivalThinkingView,thinkingConsent} from './survival-thinking.js';
import {thinkingStepBlocked} from './survival-thinking-actions.js';
import {partyMemberName} from './survival-parties.js';
import {survivalPackView} from './survival-pack.js';
const thoughtEsc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const thoughtButton=(label,value,disabled=false,action='survivalThinkingReply')=>`<button data-action="${action}" data-value="${thoughtEsc(value)}" ${disabled?'disabled':''}>${label}</button>`;
export function survivalThinkingSummary(state){const plans=survivalThinkingView(state);if(!plans.length)return '';const active=plans.find(p=>p.status==='accepted')??plans[0],m=state.survivalRun.members.find(m=>m.key===active.speaker);return `<article class="thinking-summary"><span>동료가 생각한 다음 순서</span><h2>${thoughtEsc(partyMemberName(state,m))} · ${thoughtEsc(active.label)}</h2><p>${thoughtEsc(active.evidence)}</p>${thoughtButton('계획을 듣고 함께 정하기','thinking',false,'survivalTab')}</article>`;}
export function survivalThinkingPage(state){
 const r=state.survivalRun,plans=survivalThinkingView(state),pack=survivalPackView(state),past=(r.thinking?.plans??[]).filter(p=>['completed','failed','deferred'].includes(p.status)).slice(-5).reverse();
 return `<section class="thinking-page"><header><span>관찰 → 목표 → 계획 → 대화 → 실제 행동 → 기억</span><h2>동료들은 무엇을 생각할까</h2><p>현재 파티의 동료들이 본 상황과 겪었던 일을 바탕으로 순서를 제안합니다. 동의한 뒤에도 각 단계는 직접 실행하며, 새로운 원정은 실제 출발 인원의 의사를 확인해요.</p></header>${!plans.length?'<p>지금 이야기할 수 있는 동료의 새 계획이 없어요. 파티를 꾸리거나 상황이 달라지면 다시 살펴보세요.</p>':''}${plans.map(p=>{const m=r.members.find(m=>m.key===p.speaker),step=p.steps.find(q=>q.status==='pending'),blocked=thinkingStepBlocked(state,p),refusal=thinkingConsent(state,p).find(v=>!v.agrees);return `<article class="thinking-plan" data-thinking-plan="${p.id}" data-goal="${thoughtEsc(p.goal)}"><span>${thoughtEsc(partyMemberName(state,m))} · ${p.status==='accepted'?'함께 진행 중':'먼저 꺼낸 계획'}</span><h3>${thoughtEsc(p.label)}</h3><p class="thinking-facts">지금 확인한 것: ${thoughtEsc(p.evidence)}</p><ol>${p.steps.map(q=>`<li data-thinking-step="${q.kind}" data-step-status="${q.status}">${q.status==='completed'?'✓ ':''}${thoughtEsc(q.label)}${q.result?`<small>${thoughtEsc(q.result)}</small>`:''}</li>`).join('')}</ol><div class="thinking-dialogue" aria-live="polite">${p.dialogue.map(line=>`<blockquote><strong>${line.speaker==='narrator'?'함께 확인한 내용':thoughtEsc(partyMemberName(state,r.members.find(m=>m.key===line.speaker)))}</strong><p>“${thoughtEsc(line.text)}”</p></blockquote>`).join('')}</div><div class="thinking-questions">${[['why','왜 이 순서로 하고 싶어?'],['risk','위험하거나 확실하지 않은 건?'],['companions','함께 갈 사람들 생각도 듣자']].map(([id,label])=>thoughtButton(label,p.id+'|'+id,p.questions.includes(r.day+':'+p.revision+':'+id))).join('')}${p.status==='proposed'?thoughtButton('다른 방법도 생각해보자',p.id+'|alternative',(p.alternativesUsed??0)>=2):''}</div>${p.status==='proposed'?`${thoughtButton('좋아, 이 계획으로 준비하자',p.id+'|accept',!!refusal)}${refusal?`<p class="thinking-blocked">${thoughtEsc(refusal.name+': '+refusal.line)}</p>`:''}`:''}${thoughtButton('오늘은 다른 일부터 하자',p.id+'|defer')}${p.status==='accepted'?`<section class="thinking-next"><p>다음: ${thoughtEsc(step?.label??'결과 확인')}</p>${step?.kind==='prepare'?`<p>가방 ${pack?.stats.usedSlots??0}/${pack?.stats.slots??0}칸 · ${(Number(pack?.stats.weight??0)/1000).toFixed(2)}kg. 지금 담긴 물품만 휴대합니다.</p>${thoughtButton('가방 물품 살펴보기','bag',false,'survivalTab')}`:''}${thoughtButton(step?.kind==='night'?'배급하고 밤을 넘겨 결과 확인':step?.kind==='sortie'?'이 원정으로 실제 출발 · 여력 1':step?.kind==='treat'?'치료 물품 1개 사용 · 여력 1':step?.kind==='drink'?'생수 1개 사용 · 물 마시기':step?.kind==='eat'?'음식 1개 사용 · 식사하기':step?.kind==='watch'?'감시 역할 실제로 맡기':step?.kind==='rest'?'실제로 숨고 쉬기 · 여력 1':step?.kind==='search'?'주변 물자 실제 수색 · 여력 1':step?.kind==='prepare'?'현재 준비 확인 · 다음 단계로':'다음 단계 실행',p.id,!!blocked,'survivalThinkingAct')}${blocked?`<p class="thinking-blocked">${thoughtEsc(blocked)}</p>`:''}</section>`:''}</article>`;}).join('')}${past.length?`<section class="thinking-history"><h3>계획 뒤에 남은 기억</h3>${past.map(p=>`<article data-thinking-result="${p.id}"><strong>${thoughtEsc(partyMemberName(state,r.members.find(m=>m.key===p.speaker)))} · ${thoughtEsc(p.label)}</strong><p>${p.status==='completed'?'실행 완료':p.status==='failed'?'다시 생각할 경험':'오늘은 미룬 계획'} · ${thoughtEsc(p.result)}</p></article>`).join('')}</section>`:''}</section>`;
}
